#include "KS/SRC/ks/FEPanel_shared.h"

enum { GAME_MODE_CAREER = 0, SUPER_STATE_LIE_ON_BOARD = 4 };

class ScoringManager {
    char pad[0x1b8];
    int face_points;
    int air_points;
    int tube_points;
public:
    inline void GetPartialScores(int &face, int &air, int &tube) {
        face = face_points;
        air = air_points;
        tube = tube_points;
    }
};

class kellyslater_controller {
    char pad0[0x38];
    int super_state;
    char pad1[0x10f8 - 0x3c];
    ScoringManager score_manager;
public:
    inline int get_super_state() const { return super_state; }
    inline ScoringManager &get_my_scoreManager() { return score_manager; }
};

class world_dynamics_system {
    char pad[0xf8];
    kellyslater_controller *controllers[2];
public:
    inline kellyslater_controller *get_ks_controller(int player) { return controllers[player]; }
};

class game {
    char pad0[0x74];
    int game_mode;
    char pad1[0xbc - 0x78];
    int active_player;
    char pad2[0x224 - 0xc0];
    int level_id;
public:
    inline int get_game_mode() const { return game_mode; }
    bool is_competition_level();
    inline int get_active_player() const { return active_player; }
    inline int get_level_id() const { return level_id; }
};

struct CareerData {
    char pad0[0x84];
    int goal_param_2[5];
    char pad1[220 - 0x84 - 20];
};

class IGOHintManager {
    stringx hint_text;
    TextString *instruction_text;
    float current_hint_time;
    int current_hint;
    bool competition_help;
    int hint_use[15];
public:
    enum { StandUp = 0, CompetitionNeedFace = 2, CompetitionNeedTube = 3, CompetitionNeedAir = 4 };
    void SetHint(int new_hint);
    void Update(const float dt);
};

extern world_dynamics_system *g_world_ptr;
extern game *g_game_ptr;
extern CareerData CareerDataArray[];
extern float hint_fade_in_time;
extern float hint_fade_out_time;
extern float hint_total_time;
extern float competition_hint_time;
extern float hint_boundary;
extern float timer_level_sec;

asm(".equ g_world_ptr,0x00431A8C");
asm(".equ g_game_ptr,0x0046AC64");
asm(".equ CareerDataArray,0x0042ECA0");
asm(".equ hint_fade_in_time,0x003E7620");
asm(".equ hint_fade_out_time,0x003E7624");
asm(".equ hint_total_time,0x003E7628");
asm(".equ competition_hint_time,0x003E762C");
asm(".equ hint_boundary,0x003E7630");
asm(".equ timer_level_sec,0x0046B284");
asm(".equ is_competition_level__4game,0x0027AAA8");
asm(".equ SetHint__14IGOHintManageri,0x001644C0");

#define TIMER_GetLevelSec() (timer_level_sec)

void IGOHintManager::Update(const float dt)
{
    kellyslater_controller *ksctrl = g_world_ptr->get_ks_controller(g_game_ptr->get_active_player());

    if (g_game_ptr->get_game_mode() == GAME_MODE_CAREER && g_game_ptr->is_competition_level())
    {
        if (TIMER_GetLevelSec() > competition_hint_time && !competition_help)
        {
            competition_help = true;

            int levelIdx = g_game_ptr->get_level_id();
            int facePoints, airPoints, tubePoints;
            float facePercent = 1.0f, airPercent = 1.0f, tubePercent = 1.0f;
            ksctrl->get_my_scoreManager().GetPartialScores(facePoints, airPoints,tubePoints);

            if (CareerDataArray[levelIdx].goal_param_2[0])
                facePercent = float(facePoints)/float(CareerDataArray[levelIdx].goal_param_2[0]);
            if (CareerDataArray[levelIdx].goal_param_2[1])
                airPercent = float(airPoints)/float(CareerDataArray[levelIdx].goal_param_2[1]);
            if (CareerDataArray[levelIdx].goal_param_2[2])
                tubePercent = float(tubePoints)/float(CareerDataArray[levelIdx].goal_param_2[2]);
            else
            {
                if (airPercent > facePercent)
                    tubePercent = airPercent;
                else
                    tubePercent = facePercent;
            }

            if (tubePercent <= airPercent && tubePercent <= facePercent &&
                (tubePercent + hint_boundary < airPercent || tubePercent + hint_boundary < facePercent))
                SetHint(CompetitionNeedTube);
            else if (facePercent <= airPercent && facePercent <= tubePercent &&
                (facePercent + hint_boundary < airPercent || facePercent + hint_boundary < tubePercent))
                SetHint(CompetitionNeedFace);
            else if (airPercent <= tubePercent && airPercent <= facePercent &&
                (airPercent + hint_boundary < tubePercent || airPercent + hint_boundary < facePercent))
                SetHint(CompetitionNeedAir);
        }
    }

    if (current_hint_time > hint_total_time)
        return;

    current_hint_time += dt;

    if (current_hint_time < hint_total_time - hint_fade_out_time &&
        current_hint == StandUp)
    {
        if (ksctrl->get_super_state() != SUPER_STATE_LIE_ON_BOARD)
            current_hint_time = hint_total_time - hint_fade_out_time;
    }

    if (current_hint_time < hint_fade_in_time)
        instruction_text->SetFade(current_hint_time/hint_fade_in_time);
    else if (current_hint_time > hint_total_time)
        instruction_text->SetFade(0.0f);
    else if (current_hint_time > hint_total_time - hint_fade_out_time)
        instruction_text->SetFade((hint_total_time - current_hint_time)/hint_fade_out_time);
    else
        instruction_text->SetFade(1.0f);
}
